[CmdletBinding()]
param(
    [string]$PayaraHome = 'E:\Java Institute\IdeaProjects\payara6',
    [string]$PsqlPath = 'C:\Program Files\PostgreSQL\18\pgAdmin 4\runtime\psql.exe'
)
$ErrorActionPreference='Stop';$PSNativeCommandUseErrorActionPreference=$false
$asadmin=Join-Path $PayaraHome 'bin\asadmin.bat';$base='https://localhost:8181/smartcity360/api/v1'
[xml]$d=Get-Content (Join-Path $PayaraHome 'glassfish\domains\domain1\config\domain.xml') -Raw
$r=@($d.SelectNodes("//*[local-name()='jdbc-resource']"))|Where-Object{$_.GetAttribute('jndi-name')-eq'jdbc/smartcity360'}|Select-Object -First 1
$pool=@($d.SelectNodes("//*[local-name()='jdbc-connection-pool']"))|Where-Object{$_.GetAttribute('name')-eq$r.GetAttribute('pool-name')}|Select-Object -First 1
$p=@{};@($pool.SelectNodes("./*[local-name()='property']"))|ForEach-Object{$p[$_.GetAttribute('name')]=$_.GetAttribute('value')};$p.URL-match'^jdbc:postgresql://(?<h>[^:/]+):(?<port>\d+)/(?<db>[^?]+)'|Out-Null;$dbHost=$Matches.h;$dbPort=$Matches.port;$dbName=$Matches.db
function Sql([string]$sql){$old=$env:PGPASSWORD;try{$env:PGPASSWORD=$p.password;$o=&$PsqlPath -X -v ON_ERROR_STOP=1 -h $dbHost -p $dbPort -U $p.user -d $dbName -At -c $sql 2>&1;if($LASTEXITCODE-ne0){throw($o-join"`n")};$o}finally{$env:PGPASSWORD=$old}}
function Q([string]$v){"'"+$v.Replace("'","''")+"'"}
$rng=[Security.Cryptography.RandomNumberGenerator]::Create();function Bytes([int]$n){$b=[byte[]]::new($n);$rng.GetBytes($b);$b}
function Hash([string]$plain){$salt=Bytes 16;$k=[Security.Cryptography.Rfc2898DeriveBytes]::new($plain,$salt,600000,[Security.Cryptography.HashAlgorithmName]::SHA256);$hash=$k.GetBytes(32);'sc360$1$pbkdf2-sha256$600000$'+[Convert]::ToBase64String($salt).TrimEnd('=').Replace('+','-').Replace('/','_')+'$'+[Convert]::ToBase64String($hash).TrimEnd('=').Replace('+','-').Replace('/','_')}
function Subject([string]$s){$sha=[Security.Cryptography.SHA256]::Create();try{([BitConverter]::ToString($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes($s.ToLowerInvariant())))).Replace('-','').ToLowerInvariant()}finally{$sha.Dispose()}}
$temps=New-Object Collections.Generic.List[string];$body=[IO.Path]::GetTempFileName();$temps.Add($body);$adminCookie=[IO.Path]::GetTempFileName();$temps.Add($adminCookie);$residentCookie=[IO.Path]::GetTempFileName();$temps.Add($residentCookie)
function Http([string]$path,[string]$cookie,[string]$method='GET',[string]$csrf=$null,$payload=$null){$args=@('-k','-sS','-c',$cookie,'-b',$cookie,'-o',$body,'-w','%{http_code}','-X',$method);if($method-ne'GET'){$args+=@('-H','Origin: https://localhost:8181')};if($csrf){$args+=@('-H',"X-CSRF-Token: $csrf")};if($null-ne$payload){$json=if($payload-is[string]){$payload}else{$payload|ConvertTo-Json -Compress};$args+=@('-H','Content-Type: application/json','--data-binary','@-');$code=$json|&curl.exe @args "$base$path"}else{$code=&curl.exe @args "$base$path"};[pscustomobject]@{Code=[int]$code;Body=(Get-Content $body -Raw)}}
function Login([string]$email,[string]$password,[string]$cookie){$csrfReply=Http '/auth/csrf' $cookie;$token=($csrfReply.Body|ConvertFrom-Json).token;$login=Http '/auth/login' $cookie POST $token @{email=$email;password=$password};if($login.Code-ne200){throw "Login failed: $($login.Code)"};$token}
function CreateZone([string]$type,[string]$code,[string]$name,$parent){$reply=Http '/zones' $adminCookie POST $adminCsrf @{type=$type;code=$code;name=$name;parentId=$parent};if($reply.Code-ne201){throw "Zone create failed: $($reply.Code) $($reply.Body)"};$reply.Body|ConvertFrom-Json}
$suffix=[DateTimeOffset]::UtcNow.ToUnixTimeMilliseconds();$adminId=[guid]::NewGuid();$residentId=[guid]::NewGuid();$adminEmail="phase42-admin-$suffix@test.invalid";$residentEmail="phase42-resident-$suffix@test.invalid";$adminPassword=[Convert]::ToBase64String((Bytes 24));$residentPassword=[Convert]::ToBase64String((Bytes 24));$meter1=[guid]::NewGuid();$meter2=[guid]::NewGuid();$readingIds=1..4|ForEach-Object{[guid]::NewGuid()};$zoneIds=@()
try{
 Sql "BEGIN;INSERT INTO users(id,full_name,email,password_hash,status)VALUES('$adminId','Phase 4.2 Admin',$(Q $adminEmail),$(Q (Hash $adminPassword)),'ACTIVE'),('$residentId','Phase 4.2 Resident',$(Q $residentEmail),$(Q (Hash $residentPassword)),'ACTIVE');INSERT INTO user_roles(user_id,role_code)VALUES('$adminId','ADMIN'),('$residentId','RESIDENT');COMMIT;"|Out-Null
 $adminCsrf=Login $adminEmail $adminPassword $adminCookie;$residentCsrf=Login $residentEmail $residentPassword $residentCookie
 $city=CreateZone CITY "P42-C-$suffix" 'Phase42 City' $null;$zoneIds+=$city.id;$district=CreateZone DISTRICT "P42-D-$suffix" 'Phase42 District' $city.id;$zoneIds+=$district.id;$street=CreateZone STREET "P42-S-$suffix" 'Phase42 Street' $district.id;$zoneIds+=$street.id;$b1=CreateZone BUILDING "P42-B1-$suffix" 'Phase42 Building 1' $street.id;$zoneIds+=$b1.id;$b2=CreateZone BUILDING "P42-B2-$suffix" 'Phase42 Building 2' $street.id;$zoneIds+=$b2.id;$empty=CreateZone CITY "P42-E-$suffix" 'Phase42 Empty City' $null;$zoneIds+=$empty.id
 $tree=Http "/zones/$($city.id)/tree" $adminCookie;if($tree.Code-ne200-or(($tree.Body|ConvertFrom-Json).children[0].children[0].children.Count-ne2)){throw 'Tree reconstruction failed'}
 $invalid=Http "/zones/$($b1.id)" $adminCookie PUT $adminCsrf @{code=$b1.code;name='Must Roll Back';parentId=$city.id};$afterInvalid=Http "/zones/$($b1.id)" $adminCookie;$afterInvalidJson=$afterInvalid.Body|ConvertFrom-Json;if($invalid.Code-ne409-or$afterInvalid.Code-ne200-or$afterInvalidJson.name-ne'Phase42 Building 1'){throw "Invalid reparent rollback mismatch: update=$($invalid.Code) updateBody=$($invalid.Body) get=$($afterInvalid.Code) getBody=$($afterInvalid.Body)"}
 $blockedDeactivate=Http "/zones/$($city.id)/deactivate" $adminCookie POST $adminCsrf;$emptyDeactivate=Http "/zones/$($empty.id)/deactivate" $adminCookie POST $adminCsrf;if($blockedDeactivate.Code-ne409-or$emptyDeactivate.Code-ne200){throw 'Safe deactivation behavior failed'}
 Sql "BEGIN;INSERT INTO energy_meters(id,building_zone_id,meter_code,status)VALUES('$meter1','$($b1.id)','P42-M1-$suffix','ACTIVE'),('$meter2','$($b1.id)','P42-M2-$suffix','ACTIVE');INSERT INTO energy_readings(id,meter_id,period_start_at,period_end_at,consumption_kwh)VALUES('$($readingIds[0])','$meter1','2026-11-01T00:00:00Z','2026-11-01T06:00:00Z',2.5),('$($readingIds[1])','$meter1','2026-11-01T06:00:00Z','2026-11-01T12:00:00Z',3.0),('$($readingIds[2])','$meter2','2026-11-01T00:00:00Z','2026-11-01T12:00:00Z',7.0);COMMIT;"|Out-Null
 $defaultRestore=Http "/zones/$($b2.id)/restore" $adminCookie POST $adminCsrf;$defaultRestoreJson=$defaultRestore.Body|ConvertFrom-Json;$defaultState=Sql "SELECT power_state FROM building_power_states WHERE zone_id='$($b2.id)';"|Select-Object -First 1;if($defaultRestore.Code-ne200-or$defaultRestoreJson.targetedBuildings-ne1-or$defaultRestoreJson.changedBuildings-ne0-or$defaultState-ne'ON'){throw 'Missing-state logical ON rule failed'}
 $noCsrf=Http "/zones/$($city.id)/shutdown" $adminCookie POST;$residentPower=Http "/zones/$($city.id)/shutdown" $residentCookie POST $residentCsrf;$residentUsage=Http "/zones/$($city.id)/usage?from=2026-11-01T00%3A00%3A00Z&to=2026-11-02T00%3A00%3A00Z" $residentCookie
 if($noCsrf.Code-ne403-or$residentPower.Code-ne403-or$residentUsage.Code-ne403){throw 'Zone security boundary failed'}
 $shutdown=Http "/zones/$($city.id)/shutdown" $adminCookie POST $adminCsrf;$shutdownAgain=Http "/zones/$($city.id)/shutdown" $adminCookie POST $adminCsrf;$restore=Http "/zones/$($city.id)/restore" $adminCookie POST $adminCsrf
 $s1=$shutdown.Body|ConvertFrom-Json;$s2=$shutdownAgain.Body|ConvertFrom-Json;$s3=$restore.Body|ConvertFrom-Json;if($shutdown.Code-ne200-or$s1.targetedBuildings-ne2-or$s1.changedBuildings-ne2-or$s2.changedBuildings-ne0-or$s3.changedBuildings-ne2){throw 'Power Composite counts failed'}
 $usage=Http "/zones/$($city.id)/usage?from=2026-11-01T00%3A00%3A00Z&to=2026-11-02T00%3A00%3A00Z" $adminCookie;$u=$usage.Body|ConvertFrom-Json;if($usage.Code-ne200-or[decimal]$u.totalKwh-ne[decimal]12.5-or$u.readingCount-ne3-or$u.meterCount-ne2-or$u.buildingsWithoutReadings-ne1){throw "Usage aggregation failed: $($usage.Body)"}
 Sql "INSERT INTO energy_readings(id,meter_id,period_start_at,period_end_at,consumption_kwh)VALUES('$($readingIds[3])','$meter1','2026-11-01T05:00:00Z','2026-11-01T07:00:00Z',1.0);"|Out-Null;$overlap=Http "/zones/$($city.id)/usage?from=2026-11-01T00%3A00%3A00Z&to=2026-11-02T00%3A00%3A00Z" $adminCookie;if($overlap.Code-ne409){throw 'Overlapping readings were not rejected'};Sql "DELETE FROM energy_readings WHERE id='$($readingIds[3])';"|Out-Null
 $history=Http "/zones/$($city.id)/commands" $adminCookie;$dbState=Sql "SELECT count(*) FILTER(WHERE power_state='ON')||'|'||count(*)||'|'||(SELECT string_agg(affected_buildings::text,',' ORDER BY issued_at)FROM zone_commands WHERE target_zone_id='$($city.id)') FROM building_power_states WHERE zone_id IN ('$($b1.id)','$($b2.id)');"|Select-Object -First 1;if($history.Code-ne200-or$dbState-notmatch'^2\|2\|2,0,2$'){throw "Persistence/history failed: $dbState"}
 $jobScript={param($url,$cookie,$csrf)&curl.exe -k -sS -o NUL -w '%{http_code}' -X POST -b $cookie -H 'Origin: https://localhost:8181' -H "X-CSRF-Token: $csrf" $url};$j1=Start-Job $jobScript -ArgumentList "$base/zones/$($city.id)/shutdown",$adminCookie,$adminCsrf;$j2=Start-Job $jobScript -ArgumentList "$base/zones/$($city.id)/restore",$adminCookie,$adminCsrf;$codes=@(Receive-Job -Wait $j1;Receive-Job -Wait $j2);Remove-Job $j1,$j2;if(($codes-join',')-ne'200,200'){throw "Concurrent commands failed: $($codes-join',')"};$concurrent=Sql "SELECT count(DISTINCT power_state)||'|'||count(*) FROM building_power_states WHERE zone_id IN ('$($b1.id)','$($b2.id)');SELECT count(*) FROM zone_commands WHERE target_zone_id='$($city.id)';";if($concurrent[0]-ne'1|2'-or$concurrent[1]-ne'5'){throw "Concurrent serialization failed: $($concurrent-join',')"}
 $auditCount=[int](Sql "SELECT count(*) FROM audit_logs WHERE actor_user_id='$adminId' AND action IN('ZONE_CREATED','ZONE_SHUTDOWN','ZONE_RESTORE','ZONE_DEACTIVATED');"|Select-Object -First 1);if($auditCount-lt10){throw "Audit persistence failed: $auditCount"}
 "Zone runtime: PASS (tree=200 invalid-parent=409 csrf=403 resident-power=403 resident-usage=403)";"Composite power: PASS (missing-row restore=0/ON; shutdown=2 repeat=0 restore=2; concurrent=200,200 serialized)";"Usage/JPA: PASS (12.5000 kWh, 3 readings, 2 meters, overlap=409)";"History/audit: PASS (5 city commands plus building default-state command; application audit rows=$auditCount)"
}finally{
 try{$ids=$zoneIds|ForEach-Object{"'$_'"};$idList=$ids-join',';if($idList){Sql "BEGIN;DELETE FROM audit_logs WHERE actor_user_id IN('$adminId','$residentId') OR entity_id IN($idList) OR details_json->>'subjectHash' IN('$(Subject $adminEmail)','$(Subject $residentEmail)');DELETE FROM zone_commands WHERE target_zone_id IN($idList);DELETE FROM energy_readings WHERE meter_id IN('$meter1','$meter2');DELETE FROM energy_meters WHERE id IN('$meter1','$meter2');DELETE FROM building_power_states WHERE zone_id IN($idList);DELETE FROM zones WHERE id IN($idList);DELETE FROM user_roles WHERE user_id IN('$adminId','$residentId');DELETE FROM users WHERE id IN('$adminId','$residentId');COMMIT;"|Out-Null}else{Sql "BEGIN;DELETE FROM audit_logs WHERE actor_user_id IN('$adminId','$residentId') OR details_json->>'subjectHash' IN('$(Subject $adminEmail)','$(Subject $residentEmail)');DELETE FROM user_roles WHERE user_id IN('$adminId','$residentId');DELETE FROM users WHERE id IN('$adminId','$residentId');COMMIT;"|Out-Null}}catch{Write-Warning "Cleanup failed: $($_.Exception.Message)"}
 foreach($file in $temps){Remove-Item -LiteralPath $file -Force -ErrorAction SilentlyContinue};$adminPassword=$null;$residentPassword=$null;$rng.Dispose()
}
